/*
 * arm.js — "Arm r56p0" section: the Arm Mali reference gralloc (wsialloc) from
 * VX504X08X-SW-99005-r56p0-19eac0.tar, next to the gchips fork.
 *
 * Data: site/data/arm.js (window.GRALLOC_ARM, generated by tools/extract_arm.py).
 * Size math: site/js/arm-engine.js (port of libformat + buffer_allocation.cpp).
 * Routes: #/arm, #/arm/formats, #/arm/format/<NAME>, #/arm/calc, #/arm/diff, #/arm/usage.
 * The Arm code flow lives in the shared viewer: #/flow?impl=arm.
 */
(function () {
  'use strict';
  const G = window.GX;
  const { esc, src, fmt, badge } = G;
  const A = window.GRALLOC_ARM;
  const AE = window.ArmEngine;
  if (!A || !AE) return;
  AE.init(A);
  const AU = AE.usages();
  const al = AE.loc, AF = AE.F;
  const sn = (n) => n.replace('MALI_GRALLOC_FORMAT_INTERNAL_', '').replace('HAL_PIXEL_FORMAT_', '');
  const byName = new Map(A.formats.map((f) => [f.name, f]));
  const cmpBy = new Map(A.comparison.common.map((c) => [c.name, c]));
  const onlyArm = new Set(A.comparison.only_arm);
  const hx = (v) => '0x' + BigInt(v).toString(16);
  const N = 'MALI_GRALLOC_FORMAT_INTERNAL_';

  /* ---------------- state ---------------- */
  const DEF = {
    fmt: N + 'RGBA_8888', w: 1920, h: 1080, layers: 1,
    usage: { read: 'often', write: 'often', bits: ['GRALLOC_USAGE_HW_TEXTURE'] },
    comp: { type: 'linear', afbc: { block: '16x16', tiled: false, split: false, db: false, sparse: false, ytr: false, bch: false, usm: false }, afrc: { rot: false, rgba: 16, luma: 16, chroma: 16 } },
    mode: 'auto', hal: 'HAL_PIXEL_FORMAT_RGBA_8888', capsPreset: 'readme', caps: null,
    build: { sdk: 36, hwcFbDisableAfbc: false, nonConformant: false, contiguous: false, privateFormats: true },
  };
  /* Capability presets: the README example XML (README.md:170-194) and two illustrative sets. */
  const FEATS = A.capability_features.map((f) => f.name);
  function capsFrom(ips) { const c = {}; for (const ip of AE.XIPS) c[ip] = ips[ip] ? { present: true, f: Object.assign({}, ips[ip]) } : { present: false, f: {} }; return c; }
  const allRW = (except) => FEATS.filter((n) => n !== 'DISABLED' && !(except || []).includes(n)).reduce((m, n) => (m[n] = 'RW', m), {});
  const CAPS_PRESETS = {
    readme: { label: 'README example XML (GPU + DPU)', caps: () => capsFrom(A.capability_example.ips) },
    gpu_only: { label: 'GPU XML only, every feature RW (other IPs unrestricted)', caps: () => capsFrom({ GPU: allRW() }) },
    gpu_dpu_all: { label: 'GPU + DPU XML, every feature RW', caps: () => capsFrom({ GPU: allRW(), DPU: allRW() }) },
    gpu_empty: { label: 'GPU XML with no features (nothing opt-in)', caps: () => capsFrom({ GPU: {} }) },
  };
  const saved = G.store.get('arm.calc', {});
  const st = Object.assign({}, DEF, saved);
  st.usage = Object.assign({}, DEF.usage, saved.usage || {});
  st.comp = Object.assign({}, DEF.comp, saved.comp || {});
  st.comp.afbc = Object.assign({}, DEF.comp.afbc, (saved.comp || {}).afbc || {});
  st.comp.afrc = Object.assign({}, DEF.comp.afrc, (saved.comp || {}).afrc || {});
  st.build = Object.assign({}, DEF.build, saved.build || {});
  if (!st.caps) st.caps = CAPS_PRESETS.readme.caps();
  if (!byName.has(st.fmt)) st.fmt = DEF.fmt;
  if (!A.hal_requests.some((h) => h.hal === st.hal)) st.hal = DEF.hal;
  const save = () => G.store.set('arm.calc', st);

  /* ---------------- usage model (Arm values) ---------------- */
  const READ = { none: 0n, rarely: AU.GRALLOC_USAGE_SW_READ_RARELY, often: AU.GRALLOC_USAGE_SW_READ_OFTEN };
  const WRITE = { none: 0n, rarely: AU.GRALLOC_USAGE_SW_WRITE_RARELY, often: AU.GRALLOC_USAGE_SW_WRITE_OFTEN };
  const SKIP = /^GRALLOC_USAGE_SW_(READ|WRITE)_(RARELY|OFTEN|MASK)$/;
  const FLAGS = A.usages.flags.filter((f) => f.kind === 'standard' && !SKIP.test(f.name) && f.value != null).map((f) => ({ name: f.name, value: BigInt(f.value), hex: f.value_hex, loc: f.loc, kind: 'standard' }))
    .concat(A.usages.flags.filter((f) => f.kind === 'private' && f.value !== '0' && !/_(MASK|DEFAULT|SENTINEL)$/.test(f.name))
      .map((f) => ({ name: f.name, value: BigInt(f.value), hex: f.value_hex, loc: f.loc, kind: 'private' })));
  const flag = (n) => FLAGS.find((f) => f.name === n);
  function usageValue(m) {
    let v = READ[m.read] | WRITE[m.write];
    for (const n of m.bits) { const f = flag(n); if (f) v |= f.value; }
    return v;
  }
  const PRESETS = {
    'CPU read/write only': { read: 'often', write: 'often', bits: [] },
    'GPU texture (+CPU write)': { read: 'none', write: 'often', bits: ['GRALLOC_USAGE_HW_TEXTURE'] },
    'App window (GPU render + HWC)': { read: 'none', write: 'none', bits: ['GRALLOC_USAGE_HW_RENDER', 'GRALLOC_USAGE_HW_TEXTURE', 'GRALLOC_USAGE_HW_COMPOSER'] },
    'GPU render target only': { read: 'none', write: 'none', bits: ['GRALLOC_USAGE_HW_RENDER'] },
    'Client target (FB)': { read: 'none', write: 'none', bits: ['GRALLOC_USAGE_HW_RENDER', 'GRALLOC_USAGE_HW_COMPOSER', 'GRALLOC_USAGE_HW_FB'] },
    'Video decoder → display': { read: 'none', write: 'none', bits: ['GRALLOC_USAGE_DECODER', 'GRALLOC_USAGE_HW_TEXTURE', 'GRALLOC_USAGE_HW_COMPOSER'] },
    'Camera output + CPU read': { read: 'often', write: 'none', bits: ['GRALLOC_USAGE_HW_CAMERA_WRITE'] },
    'Protected video → HWC': { read: 'none', write: 'none', bits: ['GRALLOC_USAGE_PROTECTED', 'GRALLOC_USAGE_DECODER', 'GRALLOC_USAGE_HW_COMPOSER'] },
  };
  const su = (n) => n.replace(/^GRALLOC_USAGE_/, '').replace(/^MALI_GRALLOC_USAGE_/, 'MALI_');

  /* ---------------- shared bits ---------------- */
  const TABS = [['', 'Overview'], ['formats', 'Formats'], ['calc', 'Allocation calculator'], ['caps', 'Capabilities'], ['mapper', 'Mapper & metadata'], ['handles', 'Handles & descriptors'],
    ['build', 'Build & config'], ['files', 'Source map'], ['diff', 'vs gchips'], ['usage', 'Usage flags'], ['glossary', 'Terms'], ['flow', 'Code flow']];
  const PAGES = {}, AFTERS = {};
  function sub() {
    const h = location.hash.replace(/^#\/?/, '').split('?')[0].split('/').map(decodeURIComponent);
    return { page: h[1] || '', arg: h[2] };
  }
  const tabs = (page) => `<div class="tabs">${TABS.map(([k, t]) => `<button data-arm="${k}" class="${(page === k || (page === 'format' && k === 'formats')) ? 'on' : ''}">${t}</button>`).join('')}</div>`;
  const fmtLink = (n) => byName.has(n) ? `<a class="mono" href="#/arm/format/${encodeURIComponent(n)}">${esc(sn(n))}</a>` : `<span class="mono">${esc(sn(n))}</span>`;
  const gLink = (n) => G.byName.has(n) ? `<a class="mono" href="#/format/${encodeURIComponent(n)}">${esc(sn(n))}</a>` : `<span class="mono">${esc(sn(n))}</span>`;
  const yes = (b, t) => b ? badge(t || 'yes', 'b-ok') : '<span class="muted">—</span>';
  const compBadges = (f) => [f.linear && badge('linear'), f.afbc && badge('AFBC', 'b-afbc'), f.afrc && badge('AFRC', 'b-afbc'), f.block_linear && badge('block-linear', 'b-sbwc')].filter(Boolean).join(' ');
  const ARCH = [
    ['Size / stride math', 'calc_allocation_size inside gralloc, using align_w / align_h / tile_size from formats[]', 'delegated to libformat (by DRM fourcc + modifier); formats[] align_w / align_h / tile_size are not read by the allocation code — only align_w_cpu', [al(AF.BA, 422, 521), al(AF.LF, 683, 982), al(AF.BA, 485)]],
    ['Internal format word', '64-bit; modifiers from bit 32; private range 0x1000', '32-bit; modifiers from bit 16; private range 0x100; YV12 / Y8 / Y16 remapped into the private range', [al(AF.FH, 139, 156), al(AF.FH, 51), al(AF.FH, 123, 129)]],
    ['Compression', 'AFBC (+ Exynos SBWC formats)', 'AFBC + AFRC (fixed-rate, coding units 16 / 24 / 32 B) + 16×16 block-linear', [al(AF.FH, 159, 254)]],
    ['IP capabilities', 'compiled in from board flags', 'XML files read at runtime from /vendor/etc/gralloc', [al('README.md', 17, 22)]],
    ['Unknown usage bits', 'logged only', 'allocation rejected; plus a per-format permitted_usage mask', [al(AF.FM, 1348, 1353), al(AF.FM, 1237, 1250)]],
    ['Format grading', '1 + count of AFBC modifier bits', 'AFBC_BASIC worth 2, other bits 1, AFRC 2³⁰', [al(AF.FM, 991, 1039)]],
    ['Default dataspace', 'BT709 / BT601 / BT2020 picked from size and bit depth', 'from private usage bits (colour space + range); RGB → UNKNOWN', [al(AF.FI, 1034, 1079)]],
    ['dma-buf heaps', 'system, system-uncached, camera / secure / FaceAuth heaps', 'system, system-uncached, linux,cma (build option), protected', [al(AF.HEAP, 29, 125)]],
    ['Metadata storage', 'extra dma-buf from a heap', 'shared memory, mapped at import', [al('android/src/idl_common/allocator/allocator.cpp', 118, 151), al('android/src/idl_common/mapper/mapper_common.cpp', 112, 113)]],
    ['Cache sync on lock', 'only with GRALLOC_ION_SYNC_ON_LOCK', 'always CpuSyncStart; CpuSyncEnd on unlock only if the CPU wrote', [al(AF.ACC, 90, 121)]],
    ['Size padding', '+256 B EXT_SIZE, +16 KiB for BW, Exynos +1024 per fd', 'none — libformat total only (× layers)', [al(AF.BA, 339, 369)]],
    ['Private usage bit 51', 'GRALLOC_USAGE_GOOGLE_IP_BIG (gchips)', 'MALI_GRALLOC_USAGE_RANGE_NARROW', [G.L('gralloc4/src/mali_gralloc_usages.h', 79), al(AF.USG, 81)]],
  ];

  /* ---------------- views ---------------- */
  G.views.arm = () => {
    const { page, arg } = sub();
    const head = `<h1>Arm Mali gralloc r56p0</h1>`;
    if (page === 'formats') return head + tabs(page) + formatsPage();
    if (page === 'format') return head + tabs(page) + formatPage(arg);
    if (page === 'calc') return head + tabs(page) + calcPage();
    if (page === 'diff') return head + tabs(page) + diffPage();
    if (page === 'usage') return head + tabs(page) + usagePage();
    if (PAGES[page]) return head + tabs(page) + PAGES[page](arg);
    return head + tabs('') + overviewPage();
  };

  function overviewPage() {
    const c = A.counts;
    const feats = A.features.reduce((m, f) => { (m[f.section] = m[f.section] || []).push(f); return m; }, {});
    return `<p class="lede">The Arm reference gralloc (“wsialloc”) from <code>${esc(A.meta.release)}</code>. gchips’ <code>gralloc4/</code> is a fork of an older version of this code: the same format tables and the same select → derive → allocate shape. This section shows what the newer Arm release does, with every statement linked to its line.</p>
      <div class="note small"><b>Source links:</b> Arm links (marked <span class="mono">arm:</span>) open your <b>local</b> extracted copy at <code>${esc(A.meta.root)}</code>. That folder is not part of the published site; extract the archive next to <code>site/</code> to make the links work. License: ${esc(A.meta.license)}.</div>
      <div class="grid2">
        <div class="panel"><b>What is in the archive</b><div class="kv small" style="margin-top:6px">
          <div>format table rows</div><div>${c.formats_table} ${src(A.table_locs.formats, 'formats[]')}</div>
          <div>IP support rows</div><div>${c.ip_support_table} ${src(A.table_locs.ip, 'formats_ip_support[]')}</div>
          <div>HAL → internal rows</div><div>${c.hal_to_internal_table} ${src(A.table_locs.hal_map, 'hal_to_internal_format[]')}</div>
          <div>libformat fourcc rows</div><div>${c.fourcc_entries} ${src(al(AF.LFF, 53, 156), 'libformat_map')}</div>
          <div>formats shared with gchips</div><div>${A.comparison.common.length} (only gchips ${A.comparison.only_gchips.length}, only Arm ${A.comparison.only_arm.length}) — <a href="#/arm/diff">compare</a></div>
        </div></div>
        <div class="panel"><b>Not in the archive</b><ul class="small" style="margin:6px 0 0 18px;padding:0">
          <li>The XML capability files a device ships in <code>/vendor/etc/gralloc</code> — so automatic format <em>selection</em> for a real device cannot be reproduced. The <a href="#/arm/calc">size calculator</a> models the “forced format” request instead (${src(al(AF.FM, 1185, 1216), 'select_forced_format')}).</li>
          <li>AOSP headers: <code>system/graphics.h</code> HAL values (marked “manual” where used) and the libdmabufheap heap-name constants.</li>
          <li>Build options are chosen by <code>configure</code> per Android version (${src(al('README.md', 3, 15), 'README: Build time configuration')}).</li></ul></div>
      </div>
      <h2>How the allocation path differs from gchips</h2>
      <div class="tablewrap"><table><thead><tr><th>Topic</th><th>gchips</th><th>Arm r56p0</th><th>Arm source</th></tr></thead><tbody>
      ${ARCH.map(([t, g, a, c]) => `<tr><td><b>${esc(t)}</b></td><td class="small">${esc(g)}</td><td class="small">${esc(a)}</td><td class="small">${c.map((x) => src(x)).join('<br>')}</td></tr>`).join('')}
      </tbody></table></div>
      <h2>Allocation path in r56p0</h2>
      <ol class="trace">
        <li>AIDL <code>allocator::allocate</code> → <code>allocate_common</code> ${src(al('android/src/aidl/allocator.cpp', 82, 93))}</li>
        <li><code>arm::allocator::common::allocate</code>: per buffer, allocate, then create and initialise the shared-memory metadata ${src(al('android/src/idl_common/allocator/allocator.cpp', 103, 170))}</li>
        <li><code>mali_gralloc_derive_format_and_size</code>: select format → alloc type → validate → adjust dimensions → DRM fourcc + modifier → libformat layout, stride alignment, compute ${src(al(AF.BA, 422, 521))}</li>
        <li>libformat computes per plane: aligned extent, block stride, row stride, plane size, offsets ${src(al(AF.LF, 887, 982))}</li>
        <li><code>allocator_allocate</code>: pick a dma-buf heap and allocate <code>size</code> bytes ${src(al(AF.HEAP, 103, 144))}</li>
      </ol>
      <p><a href="#/flow?impl=arm">Step through this path in the code-flow viewer →</a></p>
      <h2>Capabilities a device can declare (README)</h2>
      <p class="small muted">Feature names accepted in the runtime XML. Which ones a device enables decides the formats gralloc selects.</p>
      <div class="grid2">${Object.entries(feats).map(([s, fs]) => `<div class="panel"><b>${esc(s)}</b><div class="kv small" style="margin-top:6px">${fs.map((f) => `<div class="mono">${esc(f.feature)}</div><div>${esc(f.description.replace(/`/g, ''))} ${src(f.loc, 'README:' + f.loc.line)}</div>`).join('')}</div></div>`).join('')}</div>`;
  }

  /* --- formats list --- */
  const fq = { q: '', comp: '' };
  function formatsPage() {
    return `<div class="panel row"><input type="text" id="afq" placeholder="search name / hex value" value="${esc(fq.q)}" style="min-width:220px">
      <select id="afcomp"><option value="">any layout</option>${['linear', 'AFBC', 'AFRC', 'block-linear'].map((c) => `<option ${fq.comp === c ? 'selected' : ''}>${c}</option>`).join('')}</select>
      <span id="afcount" class="small muted"></span></div>
      <div class="tablewrap"><table><thead><tr><th>Format</th><th>Value</th><th>Planes</th><th>bpp</th><th>sub-sampling</th><th>layouts in formats[]</th><th>align_w_cpu</th><th>DRM fourcc (libformat key)</th><th>in gchips</th><th>row</th></tr></thead><tbody id="aftbody"></tbody></table></div>
      <p class="small muted">“Layouts” are the <code>.linear / .afbc / .afrc / .block_linear</code> fields of ${src(A.table_locs.formats, 'formats[]')}; libformat must also support the layout for its DRM fourcc. Values marked manual are AOSP HAL values not defined in the archive.</p>`;
  }
  function formatsAfter() {
    const tb = document.getElementById('aftbody');
    const draw = () => {
      const q = fq.q.toLowerCase();
      const rows = A.formats.filter((f) => {
        if (q && !(f.name.toLowerCase().includes(q) || (f.value_hex || '').includes(q))) return false;
        if (fq.comp === 'linear' && !f.linear) return false;
        if (fq.comp === 'AFBC' && !f.afbc) return false;
        if (fq.comp === 'AFRC' && !f.afrc) return false;
        if (fq.comp === 'block-linear' && !f.block_linear) return false;
        return true;
      });
      document.getElementById('afcount').textContent = `${rows.length} of ${A.formats.length}`;
      tb.innerHTML = rows.map((f) => {
        const d = f.drm_fourcc;
        return `<tr><td>${fmtLink(f.name)}</td><td class="mono">${esc(f.value_hex)} ${f.value_source === 'manual' ? badge('manual', 'b-manual') : ''}</td><td>${f.npln}</td><td class="mono">${f.bpp.slice(0, f.npln).join(' / ')}</td>
          <td>${f.is_yuv ? (f.hsub === 2 && f.vsub === 2 ? '4:2:0' : f.hsub === 2 ? '4:2:2' : '4:4:4') : '—'}</td><td>${compBadges(f)}</td><td>${f.align_w_cpu}</td>
          <td class="mono small">${d ? esc(d.fourcc.replace('DRM_FORMAT_', '')) + (f.drm_fourcc_fallback ? ' <span class="muted">(fallback)</span>' : '') : '<span class="badge b-bad">none</span>'}</td>
          <td>${onlyArm.has(f.name) ? badge('Arm only', 'b-afbc') : gLink(f.name)}</td><td>${src(f.row)}</td></tr>`;
      }).join('');
    };
    document.getElementById('afq').addEventListener('input', (e) => { fq.q = e.target.value; draw(); });
    document.getElementById('afcomp').addEventListener('change', (e) => { fq.comp = e.target.value; draw(); });
    draw();
  }

  /* --- format detail --- */
  const IPK = [['cpu_rd', 'CPU read'], ['cpu_wr', 'CPU write'], ['gpu_rd', 'GPU read'], ['gpu_wr', 'GPU write'], ['dpu_rd', 'Display read'], ['dpu_wr', 'Display write'], ['dpu_aeu_wr', 'Display AEU write'], ['vpu_rd', 'Video read'], ['vpu_wr', 'Video write'], ['cam_wr', 'Camera write']];
  function formatPage(name) {
    const f = byName.get(name);
    if (!f) return `<div class="err">Format <code>${esc(name)}</code> has no row in the Arm <code>formats[]</code> table.</div>`;
    const d = f.drm_fourcc, lf = d && A.fourcc_table[d.fourcc];
    const cmp = cmpBy.get(f.name);
    const comps = f.components && f.components.planes ? f.components.planes.map((p, i) => `plane ${i}: ${p.map((c) => `${c.type}${c.bits}@${c.offset}`).join(' ')}`).join('<br>') : null;
    const ipRow = f.ip ? IPK.map(([k, t]) => `<tr><td>${t}</td><td class="mono small">${(f.ip[k] || []).join(' | ') || '—'}</td></tr>`).join('') : '';
    return `<h2 class="mono" style="margin-top:4px">${esc(f.name)}</h2>
      <p class="small">Value <span class="mono">${esc(f.value_hex)}</span> ${f.value_source === 'manual' ? badge('manual — ' + (f.value_note || 'AOSP value'), 'b-manual') : ''} · defined ${src(f.defined_at)} · row ${src(f.row)}
        ${cmp ? ` · same name in gchips: ${gLink(f.name)}` : onlyArm.has(f.name) ? ' · ' + badge('not in gchips', 'b-afbc') : ''}
        · <a href="#/arm/calc" data-calc="${esc(f.name)}">open in size calculator →</a></p>
      <div class="grid2">
        <div class="panel"><b>formats[] row</b><div class="kv small" style="margin-top:6px">
          <div>planes / components</div><div>${f.npln} / ${f.ncmp.slice(0, f.npln).join(', ')}</div>
          <div>bits per pixel</div><div class="mono">${f.bpp.join(', ')} (AFBC: ${f.bpp_afbc.join(', ')})</div>
          <div>sub-sampling</div><div>hsub ${f.hsub}, vsub ${f.vsub}</div>
          <div>align_w / align_h / tile_size</div><div>${f.align_w} / ${f.align_h} / ${f.tile_size} <span class="muted">— not used by the size path</span></div>
          <div>align_w_cpu</div><div>${f.align_w_cpu} <span class="muted">— used with CPU usage</span> ${src(al(AF.BA, 485))}</div>
          <div>kind</div><div>${f.is_rgb ? 'RGB' : ''}${f.is_yuv ? 'YUV' : ''}${f.has_alpha ? ', alpha' : ''}</div>
          <div>layouts</div><div>${compBadges(f)}${f.yuv_transform ? ' ' + badge('YUV transform') : ''}${f.flex ? ' ' + badge('flex') : ''}</div>
          <div>permitted_usage</div><div class="mono small">${esc(f.permitted_usage_hex)} = ${esc(f.permitted_usage_expr)}</div>
        </div></div>
        <div class="panel"><b>IP support</b> ${src(f.ip && f.ip.row)}<div class="tablewrap" style="margin-top:6px"><table><tbody>${ipRow}</tbody></table></div>
          <p class="small muted">Most-capable support per IP; the device XML can only reduce it.</p></div>
      </div>
      <div class="grid2">
        <div class="panel"><b>DRM fourcc and libformat entry</b><div class="kv small" style="margin-top:6px">
          <div>DRM fourcc</div><div class="mono">${d ? esc(d.fourcc) + ' ' + src(d.loc) + (f.drm_fourcc_fallback ? ' (fallback table)' : '') : '—'}</div>
          ${f.name === N + 'RGB_565' ? `<div>with AFBC</div><div class="mono">DRM_FORMAT_BGR565 ${src(al(AF.DRM, 77, 81))}</div>` : ''}
          ${lf ? `<div>libformat planes</div><div>${lf.num_of_planes}</div>
          <div>bpp / bpp AFBC</div><div class="mono">${lf.bpp.join(', ')} / ${lf.bpp_afbc.join(', ')}</div>
          <div>YUV sub-sampling</div><div>${lf.yuv_subsampling || '— (not YUV)'}</div>
          <div>tile_size</div><div>${lf.tile_size}</div>
          <div>layout blocks</div><div class="mono">${lf.layout_block_info.map((b, i) => `p${i}: ${b.w}×${b.h} px = ${b.size} B`).join('<br>')}</div>
          <div>libformat supports</div><div>${[lf.is_linear && 'linear', lf.is_afbc && 'AFBC', lf.is_afrc && 'AFRC', lf.is_block_linear && 'block-linear'].filter(Boolean).join(', ') || 'nothing'} ${src(lf.loc)}</div>` : '<div>libformat</div><div><span class="badge b-unknown">no entry</span></div>'}
        </div></div>
        <div class="panel"><b>Components (mapper metadata)</b><div class="small mono" style="margin-top:6px">${comps || '<span class="muted">not listed for this format</span>'}</div>${f.components && f.components.loc ? `<div class="small">${src(f.components.loc)}</div>` : ''}
          ${cmp ? `<b style="display:block;margin-top:10px">Differences from gchips</b>${(cmp.fields.length + cmp.ip.length) ? `<div class="tablewrap"><table><thead><tr><th>field</th><th>gchips</th><th>Arm</th></tr></thead><tbody>${cmp.fields.concat(cmp.ip).map((x) => `<tr><td class="mono">${esc(x.field)}</td><td class="mono small">${esc(JSON.stringify(x.gchips))}</td><td class="mono small">${esc(JSON.stringify(x.arm))}</td></tr>`).join('')}</tbody></table></div>` : '<div class="small">identical table fields</div>'}
          <div class="small">gchips ${src(cmp.gchips_row)} · Arm ${src(cmp.arm_row)}</div>` : ''}
        </div>
      </div>
      <h2>Source row</h2><pre class="panel small" style="overflow:auto">${esc(f.row_text)}</pre>
      ${f.references && f.references.length ? `<h2>Referenced in code</h2><div class="small">${f.references.slice(0, 20).map((r) => `${src(r)} <span class="mono muted">${esc(r.text)}</span>`).join('<br>')}</div>` : ''}`;
  }
  function formatAfter() {
    document.querySelectorAll('[data-calc]').forEach((a) => a.addEventListener('click', () => { st.fmt = a.dataset.calc; save(); }));
  }

  /* --- calculator --- */
  function compOptions(f) {
    const c = st.comp, a = c.afbc, r = c.afrc;
    const multiYuv = f.is_yuv && f.npln > 1;
    const types = [['linear', 'Linear (no modifiers)', f.linear], ['afbc', 'AFBC', f.afbc], ['afrc', 'AFRC', f.afrc], ['block_linear', 'Block-linear 16×16', f.block_linear]];
    const chk = (k, t, tip) => `<label class="chk" title="${esc(tip || '')}"><input type="checkbox" data-afbc="${k}" ${a[k] ? 'checked' : ''}>${t}</label>`;
    const cu = (k, v) => `<select data-afrc="${k}">${[16, 24, 32].map((n) => `<option ${v === n ? 'selected' : ''}>${n}</option>`).join('')}</select>`;
    return `<div class="panel"><div class="row"><b>Compression</b>${types.map(([k, t, ok]) => `<label class="chk"><input type="radio" name="acomp" value="${k}" ${c.type === k ? 'checked' : ''}>${t}${ok ? '' : ' <span class="muted small">(table: no)</span>'}</label>`).join('')}</div>
      ${c.type === 'afbc' ? `<div class="row"><span class="small">superblock</span> <select data-afbc="block">${[['16x16', '16×16 (basic)'], ['32x8', '32×8 (wide)'], ['64x4', '64×4 (extra-wide)'], ['32x8_64x4', '32×8 + 64×4 (multi-plane)']].map(([k, t]) => `<option value="${k}" ${a.block === k ? 'selected' : ''}>${t}</option>`).join('')}</select>
        ${chk('tiled', 'tiled headers')}${chk('split', 'split block')}${chk('db', 'double body')}${chk('sparse', 'sparse')}${chk('ytr', 'YUV transform')}${chk('bch', 'BCH')}${chk('usm', 'USM')}</div>
        <p class="small muted">Modifier bits of the internal format ${src(al(AF.FH, 159, 200))}. Split / sparse / YTR / BCH / USM change the DRM modifier but not the size. AFBC padding is a usage bit (<code>MALI_AFBC_PADDING</code>).</p>` : ''}
      ${c.type === 'afrc' ? `<div class="row"><label class="chk"><input type="checkbox" data-afrc="rot" ${r.rot ? 'checked' : ''}>rotation layout (8×8 paging tile; off = scan 16×4)</label>
        ${multiYuv ? `<span class="small">luma CU</span> ${cu('luma', r.luma)} <span class="small">chroma CU</span> ${cu('chroma', r.chroma)}` : `<span class="small">coding unit (bytes)</span> ${cu('rgba', r.rgba)}`}</div>
        <p class="small muted">Coding-unit size bits ${src(al(AF.FH, 219, 250))}; ${multiYuv ? 'multi-plane YUV uses separate luma / chroma sizes' : 'single-plane and RGB formats use the RGBA size'} ${src(al(AF.DRM, 106, 148))}.</p>` : ''}</div>`;
  }
  function usagePicker(m) {
    const v = usageValue(m);
    const radios = (k, title) => `<span class="chk"><b>${title}</b></span>` + ['none', 'rarely', 'often'].map((o) => `<label class="chk"><input type="radio" name="au-${k}" data-u="${k}" value="${o}" ${m[k] === o ? 'checked' : ''}>${o}</label>`).join('');
    const item = (f) => `<label class="chk" title="${esc(f.hex)}"><input type="checkbox" data-flag="${esc(f.name)}" ${m.bits.includes(f.name) ? 'checked' : ''}><span class="mono">${esc(su(f.name))}</span> <span class="muted small">${f.hex}</span></label>`;
    return `<div class="panel" id="aup"><div class="row"><b>Usage</b> <span class="mono">${hx(v)}</span>
        <select data-preset><option value="">Presets…</option>${Object.keys(PRESETS).map((k) => `<option>${esc(k)}</option>`).join('')}</select></div>
      <div class="row">${radios('read', 'CPU read:')}</div><div class="row">${radios('write', 'CPU write:')}</div>
      <details><summary>Other usage flags (${m.bits.length} set)</summary><div class="flags">${FLAGS.filter((f) => f.kind === 'standard').map(item).join('')}</div>
        <p class="small"><b>Arm private bits</b> ${src(al(AF.USG, 45, 110))}</p><div class="flags">${FLAGS.filter((f) => f.kind === 'private').map(item).join('')}</div>
        <p class="small muted">Standard values parsed from ${src(al(AF.USG, 113, 144), 'usages.h')}.</p></details></div>`;
  }
  const BUILD_OPTS = [
    ['hwcFbDisableAfbc', 'GRALLOC_HWC_FB_DISABLE_AFBC', 'framebuffer (HW_FB) allocations stay linear', al('android/src/aidl/allocator.cpp', 39, 41)],
    ['nonConformant', 'GRALLOC_NON_CONFORMANT_DISPLAY', 'framebuffer forced to BGRA_8888 (configure NON_CONFORMANT_DISPLAY=y)', al(AF.FM, 1314, 1328)],
    ['contiguous', 'GRALLOC_USE_CONTIGUOUS_DISPLAY_MEMORY', 'framebuffer from the linux,cma heap', al(AF.HEAP, 111, 115)],
  ];
  function calcPage() {
    const f = byName.get(st.fmt);
    const auto = st.mode === 'auto';
    const hr = A.hal_requests.find((h) => h.hal === st.hal);
    const ipsOn = AE.XIPS.filter((ip) => st.caps[ip] && st.caps[ip].present);
    return `<p class="lede">Run a real allocation request through the Arm code: format selection (${src(al(AF.FM, 1226, 1330), 'select_best_format')}), then the size path (${src(al(AF.BA, 422, 521), 'derive_format_and_size')}) and libformat. ${auto ? 'Automatic selection uses the capability XML you set on the <a href="#/arm/caps">Capabilities</a> tab.' : 'Forced format: you choose the base format and layout yourself.'}</p>
      <div class="panel"><div class="row"><b>Request</b>
        <label class="chk"><input type="radio" name="amode" value="auto" ${auto ? 'checked' : ''}>Automatic selection (HAL format + capabilities)</label>
        <label class="chk"><input type="radio" name="amode" value="forced" ${auto ? '' : 'checked'}>Forced private format (choose the layout)</label></div>
      ${auto ? `<div class="row"><label>Requested format <select id="ahal">${A.hal_requests.map((h) => `<option value="${esc(h.hal)}" ${h.hal === st.hal ? 'selected' : ''}>${esc(h.hal.replace(/^(HAL|GRALLOC)_PIXEL_FORMAT_/, ''))} (${h.hal_value != null ? hx(h.hal_value) : '?'}) → ${esc(sn(h.internal))}</option>`).join('')}</select></label>
          ${hr ? `<span class="small">${src(hr.loc)}${hr.hal_value_source === 'manual' ? ' ' + badge('AOSP value', 'b-manual') : ''}${hr.condition ? ' ' + badge(hr.condition, 'b-unknown') : ''}</span>` : ''}</div>
        <div class="row"><label>Capability XML <select id="acaps">${Object.entries(CAPS_PRESETS).map(([k, p]) => `<option value="${k}" ${st.capsPreset === k ? 'selected' : ''}>${esc(p.label)}</option>`).join('')}<option value="custom" ${st.capsPreset === 'custom' ? 'selected' : ''}>custom (edited on the Capabilities tab)</option></select></label>
          <span class="small muted">XML present for: ${ipsOn.join(', ') || 'none'} · <a href="#/arm/caps">edit</a></span></div>
        <div class="row"><label>Android <select id="asdk">${[[35, '15 (API 35)'], [36, '16 (API 36)'], [37, '17 (API 37)']].map(([v, t]) => `<option value="${v}" ${st.build.sdk === v ? 'selected' : ''}>${t}</option>`).join('')}</select></label>
          ${BUILD_OPTS.map(([k, n, d, c]) => `<label class="chk" title="${esc(d)}"><input type="checkbox" data-build="${k}" ${st.build[k] ? 'checked' : ''}><span class="mono small">${n}</span></label>`).join('')}
          <span class="small muted">configure supports Android 15–17 (${src(al('android/configure', 68, 76), 'android/configure')})</span></div>`
      : `<div class="row"><label>Format <select id="afmt">${A.formats.map((x) => `<option value="${esc(x.name)}" ${x.name === st.fmt ? 'selected' : ''}>${esc(sn(x.name))}</option>`).join('')}</select></label>
          <label class="chk"><input type="checkbox" data-build="privateFormats" ${st.build.privateFormats ? 'checked' : ''}><span class="mono small">GRALLOC_USE_PRIVATE_FORMATS=1</span></label>
          <span class="small muted">${src(al(AF.FM, 1356, 1364))} · forced formats are built with ${src(al(AF.FH, 259, 475), 'GRALLOC_PRIVATE_FORMAT_WRAPPER_*')}</span></div>`}</div>
      <div class="panel row"><label>Width <input type="number" min="1" data-d="w" value="${st.w}"></label><label>Height <input type="number" min="1" data-d="h" value="${st.h}"></label>
        <label>Layers <input type="number" min="1" max="16" data-d="layers" value="${st.layers}"></label>
        <span class="small muted">sizes:</span> ${[[1920, 1080], [1280, 720], [3840, 2160], [4032, 3024], [1000, 999]].map(([w, h]) => `<button data-wh="${w}x${h}">${w}×${h}</button>`).join(' ')}</div>
      ${auto ? '' : compOptions(f)}${usagePicker(st.usage)}<div id="acalcout"></div>`;
  }
  function selectionTable(sel) {
    if (!sel || !sel.candidates) return '';
    const rows = sel.candidates.map((c) => `<tr class="${c.format.name === sel.chosen ? 'on' : ''}"><td>${fmtLink(c.format.name)}${c.format.name === sel.chosen ? ' ' + badge('selected', 'b-ok') : ''}${sel.request && c.format.name === sel.request.name ? ' ' + badge('requested') : ''}</td>
      <td class="small">${c.props ? esc(c.text) : '<span class="badge b-bad">not supported</span>'}</td><td>${c.grade || 0}</td><td class="small">${c.why.map(esc).join('<br>')}</td></tr>`).join('');
    return `<h2>Format selection</h2>
      <div class="kv small"><div>producers</div><div>${(sel.prod || []).join(', ') || '—'} ${src(al(AF.FM, 113, 164))}</div><div>consumers</div><div>${(sel.cons || []).join(', ') || '—'} ${src(al(AF.FM, 44, 102))}</div></div>
      <div class="tablewrap"><table><thead><tr><th>compatible base format</th><th>best layout all IPs support</th><th>grade</th><th>why</th></tr></thead><tbody>${rows}</tbody></table></div>
      <p class="small muted">Candidates are every formats[] row with the same sub-sampling, RGB/YUV kind and comparable components (${src(al(AF.FM, 910, 978), 'is_format_compatible')}). Each is checked by ${src(al(AF.FM, 827, 898), 'get_supported_format')} (AFRC → AFBC → block-linear → linear) and graded by ${src(al(AF.FM, 991, 1039), 'grade_format')}. Without CPU usage the highest grade wins; with CPU usage gralloc keeps the requested base format ${src(al(AF.FM, 1112, 1128))}.</p>`;
  }
  const PCOL = ['var(--p0)', 'var(--p1)', 'var(--p2)'];
  function byteMap(r) {
    const W = 760, total = r.allocation.total;
    if (!total) return '';
    const sc = W / total, segs = [];
    r.allocation.raw.forEach((p, i) => {
      const plane = r.layout.afbc ? Math.floor(i / 2) : i;
      segs.push({ off: p.offset, len: p.size, col: p.header ? 'var(--hdr)' : PCOL[plane], label: p.header ? `hdr ${plane}` : `plane ${plane}` });
    });
    const body = segs.map((s) => {
      const x = s.off * sc, w = Math.max(1, s.len * sc);
      return `<rect x="${x}" y="16" width="${w}" height="26" fill="${s.col}"><title>${esc(s.label)}: offset ${fmt(s.off)}, ${fmt(s.len)} bytes</title></rect>${w > 64 ? `<text x="${x + 4}" y="33" font-size="11" fill="#fff">${esc(s.label)} @${fmt(s.off)}</text>` : ''}`;
    }).join('');
    return `<svg viewBox="0 0 ${W} 48" width="100%" style="max-width:${W}px;color:var(--ink)" role="img" aria-label="buffer byte map"><text x="0" y="12" font-size="12" fill="currentColor">one dma-buf — ${fmt(total)} bytes${r.layers > 1 ? ` per layer (× ${r.layers})` : ''}</text><rect x="0" y="16" width="${W}" height="26" fill="var(--pad)"/>${body}</svg>
      <div class="legend small"><span><i style="background:var(--p0)"></i>plane 0</span><span><i style="background:var(--p1)"></i>plane 1</span><span><i style="background:var(--p2)"></i>plane 2</span><span><i style="background:var(--hdr)"></i>AFBC header</span><span><i style="background:var(--pad)"></i>alignment gap</span></div>`;
  }
  function gchipsCompare(r) {
    const auto = st.mode === 'auto';
    const hr = auto && A.hal_requests.find((h) => h.hal === st.hal);
    const gf = auto ? null : G.byName.get(st.fmt);
    const halValue = auto ? hr && hr.hal_value : gf && gf.value;
    if (halValue == null) return `<div class="panel small"><b>gchips</b>: no format of this name in gchips — nothing to compare.</div>`;
    const usage = usageValue(st.usage) & ~AU.PRIVATE_MASK;
    let g;
    try { g = G.E.allocate({ width: st.w, height: st.h, layer_count: st.layers, hal_format: halValue, usage }, G.state.flags); } catch (e) { g = { ok: false, error: String(e) }; }
    const gm = g.ok ? G.E.modNames(g.alloc_format) : [];
    return `<div class="panel"><b>Same request in gchips</b> <span class="small muted">(standard usage bits only; gchips runs its own format selection${gm.length ? ' and chose AFBC' : ''})</span>
      <div class="kv small" style="margin-top:6px">${g.ok ? `<div>selected</div><div>${gLink(g.format.name)} ${gm.map((m) => badge(m, 'b-afbc')).join('')}</div>
        <div>total</div><div><b>${fmt(g.total)}</b> bytes vs Arm <b>${fmt(r.size)}</b> (${g.total >= r.size ? '+' : ''}${fmt(g.total - r.size)})</div>
        <div>plane 0 byte stride</div><div>${fmt(g.planes[0].byte_stride)} vs Arm ${fmt(r.planes[0].row_stride)}</div>` : `<div>result</div><div class="err">${esc(g.error)}</div>`}</div>
      <p class="small muted"><a href="#/formats">Open the gchips calculator</a> for its full trace.</p></div>`;
  }
  function calcOut() {
    const out = document.getElementById('acalcout');
    if (!out) return;
    const r = AE.allocate({ mode: st.mode, hal: st.hal, caps: st.caps, build: st.build, privateFormats: st.build.privateFormats,
      format: st.fmt, width: st.w, height: st.h, layers: st.layers, usage: usageValue(st.usage), comp: st.comp });
    const trace = `<h2>Trace</h2><ol class="trace">${r.trace.map((t) => `<li class="${/^E:/.test(t.msg) ? 'err' : /^W:/.test(t.msg) ? 'note' : ''}" style="${/^[EW]:/.test(t.msg) ? 'padding:2px 6px;margin:2px 0' : ''}">${esc(t.msg)} ${src(t.cite)}</li>`).join('')}</ol>`;
    if (!r.ok) { out.innerHTML = `<div class="err"><b>Allocation fails:</b> ${esc(r.error)}</div>${selectionTable(r.selection)}${trace}`; return; }
    const at = r.alloc_type;
    const rows = r.planes.map((p, i) => `<tr><td>${i}</td><td>${fmt(p.offset)}</td><td>${fmt(p.size)}${p.header_size != null ? ` <span class="muted">(hdr ${fmt(p.header_size)} + body ${fmt(p.body_size)})</span>` : ''}</td><td>${fmt(p.row_stride)}</td><td>${fmt(p.aligned.w)} × ${fmt(p.aligned.h)}</td>
      <td class="small">${p.ext.w}×${p.ext.h} px, ${fmt(p.block_size)} B${p.sub.w > 1 || p.sub.h > 1 ? ` <span class="muted">(÷${p.sub.w}×${p.sub.h})</span>` : ''}</td><td>${fmt(p.blocks.x)} × ${fmt(p.blocks.y)}</td><td>${p.sa}</td></tr>`).join('');
    out.innerHTML = `<h2>Result</h2><div class="kv">
        <div>alloc_format</div><div class="mono">${hx(r.alloc_format)} ${fmtLink(r.format.name)} <span class="muted">data type ${r.data_type}</span></div>
        <div>allocation type</div><div>${at.primary_type}${at.is_tiled ? ', tiled headers' : ''}${at.is_padded ? ', padded' : ''}${r.mods & AE.IF.AFBC_BASIC ? (at.is_multi_plane ? ', multi-plane' : ', single-plane') : ''}</div>
        <div>DRM fourcc + modifier</div><div class="mono small">${esc(r.drm.fourcc)} · ${r.drm.modifier_hex}${r.drm.names.length ? ' (' + r.drm.names.join(' | ') + ')' : ' (LINEAR)'}</div>
        <div>dimensions given to libformat</div><div>${fmt(r.adjusted.w)} × ${fmt(r.adjusted.h)}${r.adjusted.w !== st.w || r.adjusted.h !== st.h ? ` <span class="muted">(requested ${st.w} × ${st.h})</span>` : ''}</div>
        <div>producers</div><div>${r.producers.join(', ') || 'none'} ${src(al(AF.FM, 113, 164))}</div>
        <div>size</div><div><b>${fmt(r.size)} bytes</b> (${(r.size / 1048576).toFixed(2)} MiB)${r.layers > 1 ? ` = ${fmt(r.total)} × ${r.layers} layers` : ''} ${src(al(AF.BA, 339, 369))}</div>
        <div>pixel stride (reported)</div><div>${fmt(r.pixel_stride)}${r.has_cpu ? '' : ' <span class="muted">— 0 without CPU usage</span>'}</div>
        <div>CPU lock</div><div>${r.lockable ? badge('allowed', 'b-ok') : badge('rejected: format has modifiers', 'b-bad')} ${src(r.lock_cite)}</div>
        <div>dma-buf heap</div><div>${esc(r.heap.name)} ${r.heap.note ? '<span class="small muted">' + esc(r.heap.note) + '</span>' : ''} ${src(r.heap.cite)}</div>
        <div>default dataspace</div><div class="mono small">${esc(r.dataspace.value)} ${src(r.dataspace.cite)}</div>
      </div>
      ${byteMap(r)}
      <div class="tablewrap"><table><thead><tr><th>plane</th><th>offset</th><th>size</th><th>byte stride</th><th>alloc w × h</th><th>layout block</th><th>blocks x × y</th><th>stride align</th></tr></thead><tbody>${rows}</tbody></table></div>
      <p class="small muted">Byte stride = libformat <code>average_row_stride</code> (for AFBC: bpp × width / 8, without the 128 B superblock alignment ${src(al(AF.LF, 918, 925))}). alloc w × h = <code>aligned_extent</code>. No extra bytes are added after libformat’s total.</p>
      ${selectionTable(r.selection)}${gchipsCompare(r)}${trace}`;
  }
  function calcAfter() {
    const rerender = () => { save(); G.render(); };
    const on = (id, ev, fn) => { const el = document.getElementById(id); if (el) el.addEventListener(ev, fn); };
    on('afmt', 'change', (e) => { st.fmt = e.target.value; rerender(); });
    on('ahal', 'change', (e) => { st.hal = e.target.value; rerender(); });
    on('asdk', 'change', (e) => { st.build.sdk = Number(e.target.value); rerender(); });
    on('acaps', 'change', (e) => { st.capsPreset = e.target.value; if (CAPS_PRESETS[st.capsPreset]) st.caps = CAPS_PRESETS[st.capsPreset].caps(); rerender(); });
    document.querySelectorAll('input[name="amode"]').forEach((i) => i.addEventListener('change', () => { st.mode = i.value; rerender(); }));
    document.querySelectorAll('[data-build]').forEach((i) => i.addEventListener('change', () => { st.build[i.dataset.build] = i.checked; rerender(); }));
    document.querySelectorAll('input[data-d]').forEach((i) => i.addEventListener('change', () => { st[i.dataset.d] = Math.max(1, Math.floor(Number(i.value) || 1)); rerender(); }));
    document.querySelectorAll('button[data-wh]').forEach((b) => b.addEventListener('click', () => { const [w, h] = b.dataset.wh.split('x').map(Number); st.w = w; st.h = h; rerender(); }));
    document.querySelectorAll('input[name="acomp"]').forEach((i) => i.addEventListener('change', () => { st.comp.type = i.value; rerender(); }));
    document.querySelectorAll('[data-afbc]').forEach((i) => i.addEventListener('change', () => { const k = i.dataset.afbc; st.comp.afbc[k] = i.type === 'checkbox' ? i.checked : i.value; rerender(); }));
    document.querySelectorAll('[data-afrc]').forEach((i) => i.addEventListener('change', () => { const k = i.dataset.afrc; st.comp.afrc[k] = i.type === 'checkbox' ? i.checked : Number(i.value); rerender(); }));
    const up = document.getElementById('aup');
    up.querySelectorAll('input[data-u]').forEach((i) => i.addEventListener('change', () => { st.usage[i.dataset.u] = i.value; rerender(); }));
    up.querySelectorAll('input[data-flag]').forEach((i) => i.addEventListener('change', () => {
      const n = i.dataset.flag; st.usage.bits = st.usage.bits.filter((x) => x !== n); if (i.checked) st.usage.bits.push(n); rerender();
    }));
    up.querySelector('select[data-preset]').addEventListener('change', (e) => { const p = PRESETS[e.target.value]; if (p) { st.usage = { read: p.read, write: p.write, bits: p.bits.slice() }; rerender(); } });
    if (st.usage.bits.length) up.querySelector('details').open = true;
    calcOut();
  }

  /* --- diff --- */
  function diffPage() {
    const common = A.comparison.common;
    return `<p class="lede">Format tables side by side, matched by internal format name. gchips data: commit ${esc((G.FD.meta.commit || '').slice(0, 12))}; Arm: r56p0.</p>
      <div class="grid2">
        <div class="panel"><b>Only in Arm r56p0 (${A.comparison.only_arm.length})</b><div class="small" style="margin-top:6px">${A.comparison.only_arm.map(fmtLink).join(', ')}</div></div>
        <div class="panel"><b>Only in gchips (${A.comparison.only_gchips.length})</b><div class="small" style="margin-top:6px">${A.comparison.only_gchips.map(gLink).join(', ')}</div>
          <p class="small muted">Exynos / SBWC / Google vendor formats and a few YUV variants the Arm release does not have.</p></div>
      </div>
      <h2>Shared formats (${common.length}) — table differences</h2>
      <div class="tablewrap"><table><thead><tr><th>Format</th><th>value g / a</th><th>formats[] fields that differ</th><th>IP support that differs</th><th>rows</th></tr></thead><tbody>
      ${common.map((c) => `<tr><td>${fmtLink(c.name)}</td><td class="mono small">${hx(c.value_gchips)} / ${hx(c.value_arm)}</td>
        <td class="small">${c.fields.map((x) => `<span class="mono">${esc(x.field)}</span>: ${esc(JSON.stringify(x.gchips))} → ${esc(JSON.stringify(x.arm))}`).join('<br>') || '<span class="muted">same</span>'}</td>
        <td class="small">${c.ip.map((x) => `<span class="mono">${esc(x.field)}</span>: ${esc(x.gchips.join('|'))} → ${esc(x.arm.join('|'))}`).join('<br>') || '<span class="muted">same</span>'}</td>
        <td class="small">${src(c.gchips_row, 'gchips:' + c.gchips_row.line)}<br>${src(c.arm_row)}</td></tr>`).join('')}
      </tbody></table></div>
      <p class="small muted">In Arm r56p0 the <code>align_w / align_h / tile_size</code> columns are not used for sizing (libformat decides), so a difference there does not by itself mean a different buffer size. Use the <a href="#/arm/calc">calculator</a>: it shows the gchips result for the same request.</p>`;
  }

  /* --- usage --- */
  function usagePage() {
    const g = A.usages.groups;
    return `<p class="lede">Usage bits as defined in ${src(al(AF.USG, 1), 'android/src/usages.h')}. Standard values match AOSP; the private (vendor) bits mean different things than in gchips.</p>
      <div class="tablewrap"><table><thead><tr><th>Flag</th><th>Value</th><th>Defined</th></tr></thead><tbody>
      ${A.usages.flags.map((f) => `<tr><td class="mono">${esc(f.name)}</td><td class="mono">${esc(f.value_hex)}</td><td>${src(f.loc)}</td></tr>`).join('')}
      </tbody></table></div>
      <h2>Groups</h2><div class="kv small">${Object.entries(g).map(([k, v]) => `<div class="mono">${esc(k)}</div><div class="mono">${esc(v.value_hex)} ${src(v.loc)}</div>`).join('')}</div>
      <h2>Where usage decides the layout</h2><ol class="trace">
        <li>Bits outside <code>VALID_USAGE</code> reject the allocation ${src(al(AF.FM, 1348, 1353))}</li>
        <li>Every format row has a <code>permitted_usage</code> mask checked during automatic selection ${src(al(AF.FM, 1237, 1250))}</li>
        <li>CPU usage: stride aligned to <code>align_w_cpu</code> pixels and pixel stride reported ${src(al(AF.BA, 479, 495))}</li>
        <li>“GPU” usage = any bit other than CPU, private and FRONTBUFFER: stride aligned to 64 B (RGB) / 128 B (YUV) ${src(al(AF.BA, 480, 481))} ${src(al(AF.LF, 618, 639))}</li>
        <li>GPU producer + AFBC: width/height aligned to 16; video decoder + AFBC YUV 4:2:0: height + 16 (tiled) or + 32 ${src(al(AF.FM, 178, 215))}</li>
        <li><code>MALI_GRALLOC_USAGE_AFBC_PADDING</code>: AFBC rows padded to 4 superblocks for RGB ${src(al(AF.BA, 152, 155))} ${src(al(AF.LF, 208, 216))}</li>
        <li>Heap: PROTECTED → protected; FB without encoder → system (or linux,cma); CPU read often → system (cached); else system-uncached ${src(al(AF.HEAP, 103, 125))}</li>
        <li>Colour space / range private bits → default dataspace for YUV ${src(al(AF.FI, 1034, 1079))}</li>
        <li>AFRC is only chosen when the usage carries an RGBA/luma coding size (bits 28–30) and, for YUV, a chroma coding size (bits 55–56) ${src(al(AF.USG, 92, 110))} ${src(al(AF.FM, 640, 680))}</li></ol>
      <div class="note small"><b>Shared bits:</b> the AFRC luma/RGBA coding sizes reuse private bits 0–2: size 16 = PRIVATE_2|PRIVATE_0 (PRIVATE_0 is MALI_GRALLOC_USAGE_FRONTBUFFER) and size 24 = PRIVATE_2|PRIVATE_1 (PRIVATE_1 is MALI_GRALLOC_USAGE_NO_AFBC). So front-buffer and no-AFBC checks ignore those bits whenever the AFRC sentinel PRIVATE_2 is set ${src(al(AF.USG, 215, 237))}.</div>`;
  }

  G.AFTER.arm = () => {
    document.querySelectorAll('[data-arm]').forEach((b) => b.addEventListener('click', () => {
      const k = b.dataset.arm;
      location.hash = k === 'flow' ? '#/flow?impl=arm' : '#/arm' + (k ? '/' + k : '');
    }));
    const { page } = sub();
    if (page === 'formats') formatsAfter();
    else if (page === 'format') formatAfter();
    else if (page === 'calc') calcAfter();
    else if (AFTERS[page]) AFTERS[page](sub().arg);
  };

  /* ---------------- code-flow data for the Arm implementation ---------------- */
  const MC = 'android/src/idl_common/mapper/mapper_common.cpp';
  const J = {
    aidl_allocate: [1], allocate_common: [1], common_allocate: [1], buffer_allocate: [1], derive: [1], select_format: [1], select_best: [1], get_best: [1],
    get_alloc_type: [1], adjust_dims: [1], drm_params: [1], lf_layout: [1], lf_stride: [1], lf_compute: [1], update_desc: [1], allocator_allocate: [2], pick_heap: [2],
    import_buffer: [0], lock_buffer: [0], gralloc_lock: [0], validate_lock: [0], map_buffer: [0], allocator_map: [2], buffer_sync: [0],
    unlock_buffer: [0], gralloc_unlock: [0], free_buffer: [0], unmap_buffer: [0], allocator_unmap: [2],
  };
  // [handle, fds, metadata, CPU mapping, lock_count, cpu_write, cite] — written from the cited lines
  const STATE_AT = {
    'allocate:aidl_allocate': ['descriptor received', '—', '—', 'no', '—', '—', al('android/src/aidl/allocator.cpp', 87, 92)],
    'allocate:derive': ['layout computed (alloc_format, plane_info, size)', '—', '—', 'no', '—', '—', al(AF.BA, 519)],
    'allocate:update_desc': ['descriptor: size (× layers), pixel_stride, plane_info', '—', '—', 'no', '—', '—', al(AF.BA, 342, 368)],
    'allocate:pick_heap': ['private_handle_t created', 'buffer dma-buf fd from the chosen heap', 'created next by common::allocate (shared memory)', 'no', '—', '—', al(AF.HEAP, 132, 143)],
    'import:import_buffer': ['cloned, import_pid set, added to RegisteredHandlePool', 'dup’d fds', 'mmap’d at import (attr_base)', 'no (base = nullptr)', '0', '0', al(MC, 102, 128)],
    'lock:allocator_map': ['imported', 'dup’d fds', 'mapped', 'yes — mmap once (base)', '0', '0', al(AF.HEAP, 183, 190)],
    'lock:buffer_sync': ['locked', 'dup’d fds', 'mapped', 'yes', 'lock_count++ (1)', 'set for a write lock; CpuSyncStart', al(AF.ACC, 94, 98)],
    'unlock:buffer_sync': ['unlocked', 'dup’d fds', 'mapped', 'yes — stays mapped until free', 'lock_count-- (0)', 'CpuSyncEnd only if cpu_write; cleared at 0', al(AF.ACC, 104, 119)],
    'free:free_buffer': ['removed from pool', 'dup’d fds', 'munmap’d if imported by this process', 'unmapping…', '—', '—', al(MC, 153, 164)],
    'free:unmap_buffer': ['removed from pool; import_pid = -1', 'closed when the handle is deleted', 'munmap’d', 'no (base = nullptr)', '0', '0', al(AF.ACC, 444, 453)],
  };
  const PHASE_ORDER = ['allocate', 'import', 'lock', 'unlock', 'free'];
  function stateFor(phase, idx) {
    let last = null;
    for (const ph of PHASE_ORDER) {
      const ids = A.callflow.paths[ph];
      for (let k = 0; k < ids.length; k++) {
        const s = STATE_AT[ph + ':' + ids[k]];
        if (s) last = { id: ids[k], s };
        if (ph === phase && k === idx) return last;
      }
    }
    return last;
  }
  G.flowJourneyArm = {
    LANES: ['Client process (mapper)', 'Allocator service', 'Kernel (dma-buf)'], PHASE_ORDER, J, STATE_AT, stateFor,
    STATE_NAMES: ['handle', 'fds', 'metadata', 'CPU mapping', 'lock_count', 'cpu_write'],
    INTRO: 'Watch the Arm r56p0 gralloc code run for one buffer: allocated by the allocator service (including libformat’s size math), then imported, locked, unlocked and freed by an app.',
  };
  G.ARM = A;
  G.ARMX = { A, AE, AU, st, save, sn, fmtLink, gLink, byName, al, AF, hx, PAGES, AFTERS, FLAGS, usageValue, CAPS_PRESETS, capsFrom, tabs, FEATS, compBadges };
})();
